<?php require_once __DIR__ . '/../includes/bootstrap.php';$u=require_login('employer');$p=database();$jobId=(int)($_GET['job_id']??$_POST['job_id']??0);$s=$p->prepare('SELECT id,title FROM jobs WHERE id=? AND employer_id=?');$s->execute([$jobId,$u['id']]);$job=$s->fetch();if(!$job)exit('Job not found.');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(posted('action')==='delete')$p->prepare('DELETE q FROM quiz_questions q JOIN jobs j ON j.id=q.job_id WHERE q.id=? AND j.employer_id=?')->execute([(int)$_POST['question_id'],$u['id']]);else{$order=(int)$p->query('SELECT COALESCE(MAX(display_order),0)+1 FROM quiz_questions WHERE job_id='.$jobId)->fetchColumn();$p->prepare('INSERT INTO quiz_questions(job_id,question_text,option_a,option_b,option_c,option_d,correct_option,marks,display_order) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$jobId,posted('question'),posted('a'),posted('b'),posted('c'),posted('d'),posted('correct'),posted('marks'),$order]);}redirect('quiz-builder.php?job_id='.$jobId);}$s=$p->prepare('SELECT * FROM quiz_questions WHERE job_id=? ORDER BY display_order');$s->execute([$jobId]);page_header('Quiz builder');?><h1><?=e($job['title'])?> quiz</h1><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=csrf_token()?>"><input type="hidden" name="job_id" value="<?=$jobId?>"><div class="full"><label>Question</label><textarea name="question" required></textarea></div><?php foreach(['a','b','c','d'] as $letter):?><div><label>Option <?=strtoupper($letter)?></label><input name="<?=$letter?>" required></div><?php endforeach;?><div><label>Correct option</label><select name="correct"><option>A</option><option>B</option><option>C</option><option>D</option></select></div><div><label>Marks</label><input type="number" min="1" name="marks" value="1"></div><div class="full"><button>Add question</button></div></form><table><tr><th>Question</th><th>Marks</th><th></th></tr><?php foreach($s as $q):?><tr><td><?=e($q['question_text'])?></td><td><?=e($q['marks'])?></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?=csrf_token()?>"><input type="hidden" name="job_id" value="<?=$jobId?>"><input type="hidden" name="question_id" value="<?=$q['id']?>"><input type="hidden" name="action" value="delete"><button class="small">Delete</button></form></td></tr><?php endforeach;?></table><?php page_footer(); ?>